                            $rowMoneyGot = sqlFetchArray($resMoneyGot);
                            $MoneyGot = $rowMoneyGot['MoneyGot'];
                            //supports both mapped and unmapped code_type in ar_activity
                            $resMoneyAdjusted = sqlStatement(
